services.forEach((s,i)=>{let a=document.createElement('article');a.className='service-card';a.innerHTML=`<div class="service-number"><span>0${i+1}</span><span>RESIDENTIAL VALUATION</span></div><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true"><path d="${paths[i]}"/></svg><h3>${s[0]}</h3><p>${s[1]}</p><button class="card-link" data-service="${i}">Explore service <span>↗</span></button>`;track.append(a)});
const prev=document.querySelector('#prev'),next=document.querySelector('#next');function updateSlider(){let n=Math.round(track.scrollLeft/(track.children[0].offsetWidth+20));document.querySelector('#slide-count').textContent=`${String(n+1).padStart(2,'0')} / 08`;prev.disabled=track.scrollLeft<5;next.disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-5}function slide(dir){track.scrollBy({left:dir*(track.children[0].offsetWidth+20),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}prev.onclick=()=>slide(-1);next.onclick=()=>slide(1);track.addEventListener('scroll',updateSlider,{passive:true});track.addEventListener('keydown',e=>{if(e.target===track&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();slide(e.key==='ArrowLeft'?-1:1)}});updateSlider();window.addEventListener('resize',updateSlider);
const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
let frame=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)');function onScroll(){if(frame)return;frame=true;requestAnimationFrame(()=>{document.querySelector('#header').classList.toggle('compact',scrollY>50);if(!reduced.matches&&scrollY<1000)document.querySelector('.hero-image').style.transform=`translateY(${Math.min(scrollY*.16,130)}px) scale(1.04)`;frame=false})}window.addEventListener('scroll',onScroll,{passive:true});onScroll();
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.onclick=()=>{let open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open);menu.textContent=open?'×':'☰'};nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open'))menu.click()});
const dialog=document.querySelector('dialog');document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{const i=+b.dataset.service;document.querySelector('#dialog-title').textContent=services[i][0];document.querySelector('#dialog-copy').textContent=services[i][2];document.querySelector('select').selectedIndex=i+1;const reading=document.querySelector("#dialog-reading");const rental=[2,3,4].includes(i);reading.href=rental?"/insights/is-house-hacking-worth-it-2026/":"/insights/should-you-buy-a-house-in-2026/";reading.textContent=rental?"Related insight: house hacking and rental cash flow ↗":"Related insight: should you buy now or wait? ↗";dialog.showModal()});document.querySelector('.close').onclick=()=>dialog.close();document.querySelector('#dialog-cta').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
document.querySelectorAll('.towns button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.towns button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelector('.town-detail').textContent=`Residential appraisals in ${b.textContent}, with insight into neighborhood context, property characteristics and local comparables.`});
document.querySelector('#quote-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);document.querySelector('#form-result').textContent=`Request preview ready for ${data.get('name')}: ${data.get('service')} at ${data.get('address')}. This preview has not been sent. Contact delivery is awaiting confirmed business details.`};document.querySelector('#year').textContent=new Date().getFullYear();
